        moveMatchingTargetCandidates() {
            if(!this.moveMatching.sourceGroupId) return []
            return this.links.filter(g => g.linkGroup.id != this.moveMatching.sourceGroupId)
        },
        canConfirmMoveMatching() {
            return !!this.moveMatching.host && !!this.moveMatching.selectedTargetId
        },
        filteredLinkCount() {
            return this.filteredLinks.reduce((sum, g) => sum + g.links.length, 0)
        },
        filteredLinks() {
            if (!this.searchQuery.trim()) return this.links
            const q = this.searchQuery.trim().toLowerCase()
            const field = this.searchField
            return this.links.reduce((acc, g) => {
                const groupTitle = (g.linkGroup.title || '').toLowerCase()
                const groupTitleMatch = (field === 'all' || field === 'groupTitle') && groupTitle.includes(q)
                const matchingLinks = (field === 'all' || field === 'linkTitle' || field === 'url')
                    ? g.links.filter(l =>
                        (field === 'all' || field === 'linkTitle') && (l.title || '').toLowerCase().includes(q) ||
                        (field === 'all' || field === 'url') && (l.link || '').toLowerCase().includes(q)
                    )
                    : []
                if (groupTitleMatch || matchingLinks.length > 0) {
                    acc.push(groupTitleMatch && matchingLinks.length === g.links.length
                        ? g
                        : { linkGroup: g.linkGroup, links: groupTitleMatch ? g.links : matchingLinks, showHostMenu: g.showHostMenu }
                    )
                }
                return acc
            }, [])
        },
        groupHeights() {
            return this.filteredLinks.map(g => {
                const id = String(g.linkGroup.id)
                if (this.measuredHeights[id] !== undefined) return this.measuredHeights[id]
                return 90 + g.links.length * 28 + 32
            })
        },
        groupOffsets() {
            const offsets = []
            let acc = 0
            this.groupHeights.forEach(h => { offsets.push(acc); acc += h })
            return offsets
        },
        totalHeight() {
            if (!this.filteredLinks.length) return 0
            const n = this.filteredLinks.length
            return this.groupOffsets[n - 1] + this.groupHeights[n - 1]
        },
        visibleGroups() {
            const overscan = 300
            const viewTop = this.scrollTop - this.mainStart - overscan
            const viewBottom = this.scrollTop - this.mainStart + this.viewportHeight + overscan
            return this.filteredLinks.reduce((acc, group, i) => {
                const top = this.groupOffsets[i]
                const bottom = top + this.groupHeights[i]
                if (bottom > viewTop && top < viewBottom) acc.push({ group, offset: top })
                return acc
            }, [])
        }
    },
    mounted() {
        this._onScroll = () => {
            if (!this._scrollRAF) {
                this._scrollRAF = requestAnimationFrame(() => {
                    this.scrollTop = window.scrollY
                    this._scrollRAF = null
                })
            }
        }
        this._onResize = () => {
            this.viewportHeight = window.innerHeight
            this.updateMainStart()
        }
        window.addEventListener('scroll', this._onScroll, { passive: true })
        window.addEventListener('resize', this._onResize, { passive: true })
        if (!this.faviconDbReady) this.faviconDbReady = this.initFaviconDB()
        this.$nextTick(() => {
            this.updateMainStart()
            this.measureGroupHeights()
        })
    },
    updated() {
        this.$nextTick(() => {
            this.updateMainStart()
            this.measureGroupHeights()
        })
    },
    beforeDestroy() {
        window.removeEventListener('scroll', this._onScroll)
        window.removeEventListener('resize', this._onResize)
    },
    methods: {
        updateMainStart() {
            if (this.$refs.mainEl) {
                this.mainStart = this.$refs.mainEl.getBoundingClientRect().top + window.scrollY
            }
        },
        measureGroupHeights() {
            if (!this.$refs.mainEl) return
            this.$refs.mainEl.querySelectorAll('[data-group-id]').forEach(el => {
                const id = el.getAttribute('data-group-id')
                const h = el.offsetHeight + 32 // offsetHeight + margin-bottom (2em ≈ 32px)
                if (this.measuredHeights[id] !== h) this.$set(this.measuredHeights, id, h)
            })
        },
        async initFaviconDB() {
            try {
                const db = await openFaviconDB()
                this.faviconDb = db
                const all = await idbGetAll(db)
                Object.keys(all).forEach(hostname => {
                    const blob = all[hostname]
                    if (blob && blob.type.startsWith('image/')) {
                        this.$set(this.faviconDataUrls, hostname, URL.createObjectURL(blob))
                    } else {
                        idbDelete(db, hostname) // purge poisoned non-image entry so loadFavicons re-fetches it
                    }
                })
            } catch(e) { /* IndexedDB unavailable (private mode, quota) - fall back to fetching without cache */ }
        },
        hostname(url) {
            return getHostname(url)
        },
        async loadFavicons(linkGroups) {
            if (!this.faviconDbReady) this.faviconDbReady = this.initFaviconDB()
            await this.faviconDbReady
            const hostnames = new Set()
            linkGroups.forEach(g => {
                g.links.forEach(l => {
                    const h = getHostname(l.link)
                    if (h && !this.faviconDataUrls[h]) hostnames.add(h)
                })
            })
            const db = this.faviconDb
            const authToken = [REDACTED]'authToken')
            await Promise.all([...hostnames].map(async hostname => {
                try {
                    const res = await fetch(`/favicon-proxy?hostname=${encodeURIComponent(hostname)}`, {
                        headers: { 'authToken': authToken }
                    })
                    if (res.ok) {
                        const blob = await res.blob()
                        if (db) await idbPut(db, hostname, blob)
                        this.$set(this.faviconDataUrls, hostname, URL.createObjectURL(blob))
                    }
                } catch(e) { /* silently ignore network errors */ }
            }))
        },
        deleteLink(id) {
            deleteLink(id)
        },
        switchToRegistrationForm() {
            this.authError = false
            this.register = true
        },
        switchToLoginForm() {
            this.authError = false
            this.register = false
        },
        loginUser(username = null, password = null, callback = null) {
            if(!username || !password) {
                username = this.username
                password = [REDACTED]
                // console.log('loginUser', 'fresh')
            } else {
                // console.log('loginUser', 'renew token')
            }

            fetch('/authenticate', {
                method: 'post',
                headers: {
                    'Accept': 'application/json',
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({ username: username, password: password })
            })
            .then(res => res.json())
            .then(res => {
                if(res.success) {
                    localStorage.setItem('authToken', res.token)
                    if(callback) {
                        callback()
                    } else {
                        getLinks()
                    }
                    localStorage.setItem('username', username)
                    localStorage.setItem('password', password)
                    this.authError = null
                    this.username = null
                    this.password = null
                } else {
                    this.authError = res.message
                }
            })
        },
        registerUser() {
            fetch('/register', {
                method: 'post',
                headers: {
                    'Accept': 'application/json',
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({ username: this.username, password: [REDACTED] })
            })
            .then(res => res.json())
            .then(res => {
                if(res.success) {
                    this.loginUser()
                    this.authError = null
                    this.username = null
                    this.password = null
                } else {
                    this.authError = res.message.replace('Authentication', 'Registration')
                }
            })
        },
        logout() {
            if(confirm('Are you sure you want to logout?')) {
                localStorage.clear()
                getLinks()
            }
        },
        openAllInGroup(linkGroup) {
            var popupBlocked = false
            linkGroup.links.forEach(linkObj => {
                var popup = window.open(linkObj.link)
                if(popup) {
                    this.deleteLink(linkObj.id)
                } else {
                    popupBlocked = true
                }
            })
            if(popupBlocked) {
                alert("Please allow popups for this site in your site settings")
            }
        },
        deleteAllInGroup(linkGroup) {
            if(confirm("Are you sure?")) {
                linkGroup.links.forEach(linkObj => {
                    this.deleteLink(linkObj.id)
                })
            }
        },
        copyAllInGroupToClipboard(linkGroup) {
            var clipboardText = ''
            linkGroup.links.forEach(linkObj => {
                clipboardText += linkObj.link + '\n'
            })
            navigator.clipboard.writeText(clipboardText)
            alert(`${linkGroup.links.length} links copied to clipboard`)
        },
        toggleHostMenu(linkGroup) {
            this.$set(linkGroup, 'showHostMenu', !linkGroup.showHostMenu)
        },
        hideHostMenu(linkGroup) {
            this.$set(linkGroup, 'showHostMenu', false)
        },
        uniqueHosts(links) {
            const hosts = new Set()
            links.forEach(l => {
                try {
                    const u = new URL(l.link)
                    hosts.add(u.host)
                } catch(e) { /* ignore invalid urls */ }
            })
            return Array.from(hosts).sort()
        },
        createNewGroupWithHost(linkGroup, event) {
            const host = event.target.value
            if(!host) return
            const linkIds = linkGroup.links.filter(l => {
                try { return new URL(l.link).host === host } catch(e) { return false }
            }).map(l => l.id)
            const defaultTitle = `${host}`
            const title = prompt('New Group Name (optional)', defaultTitle)
            if (title === null) { // user cancelled -> do nothing
                event.target.value = ''
                this.$set(linkGroup, 'showHostMenu', false)
                return
            }
            createGroupWithLinks(linkIds, title)
            this.$set(linkGroup, 'showHostMenu', false)
            event.target.value = ''
        },
        momentDateTime(dateTime) {
            return moment.utc(dateTime).local().format('DD-MMM-YY h:mm A')
        },
        onDrag(link, event) {
            event.dataTransfer.setData('link', JSON.stringify(link))
        },
        onDrop(linkGroup, event) {
            var link = JSON.parse(event.dataTransfer.getData('link'))
            changeLinkGroup(link.id, linkGroup.linkGroup.id)
            if(linkGroup.linkGroup.id !== link.link_group_id) { // ensures the link isn't added back to the same group as it was dragged from
                this.$store.state.links.forEach((linkGroup, index) => {
                    if(linkGroup.linkGroup.id == link.link_group_id) {
                        linkGroup.links = linkGroup.links.filter(aLink => aLink.id !== link.id)
                    }
                    if(linkGroup.links.length == 0) { // if a linkGroup is empty
                        app.$store.state.links.splice(index, 1) // remove it from the array
                    }
                })
                link.link_group_id = linkGroup.linkGroup.id
                linkGroup.links.unshift(link)
            }
        },
        viewAPIKeys() {
            this.fetchAPIKeys()
            this.$modal.show('view-api-keys')
        },
        fetchAPIKeys(callback=null) {
            let authToken = [REDACTED]'authToken')
            fetch('/api-key/list', {
                method: 'get',
                headers: {
                    'Accept': 'application/json',
                    'Content-Type': 'application/json',
                    'authToken': authToken
                }
            })
            .then(response => response.json())
            .then(response => {
                if(response.hasOwnProperty('success') && !response.success) {
                    alert('Auth failed')
                } else {
                    this.apiKeys = response
                    if(callback) {
                        callback()
                    }
                }
            })
        },
        generateAPIKey() {
            this.generatingAPIKey = true
            let authToken = [REDACTED]'authToken')
            fetch('/api-key/generate', {
                method: 'post',
                headers: {
                    'Accept': 'application/json',
                    'Content-Type': 'application/json',
                    'authToken': authToken
                }
            })
            .then(response => response.json())
            .then(response => {
                if(response.hasOwnProperty('success') && !response.success) {
                    alert('Auth failed')
                } else {
                    this.fetchAPIKeys()
                }
                this.generatingAPIKey = false
            })
        },
        createLoader(loaderMessage) {
            let loader = document.createElement('div')
            loader.style.cssText = `
                position: fixed;
                background-color: #00000036;
                height: 100vh;
                width: 100vw;
                z-index: 1000;
                top: 0;
            `
            loader.innerHTML = `
                <div style="height: 100vh; display: flex; justify-content: center; align-items: center; color: white; font-size: 2em;">${loaderMessage}</div>
            `
            document.body.appendChild(loader)
            return loader
        },
        deleteAPIKey(id) {
            let loader = this.createLoader('Deleting...')
            let authToken = [REDACTED]'authToken')
            fetch(`/api-key/delete/${id}`, {
                method: 'delete',
                headers: {
                    'Accept': 'application/json',
                    'Content-Type': 'application/json',
                    'authToken': authToken
                }
            }).then(() => {
                this.fetchAPIKeys(() => loader.remove())
            })
        },
        renameLinkGroup(linkGroup) {
            let linkGroupName = prompt('Link Group Name', linkGroup.title ? linkGroup.title : '')

            if(linkGroupName || linkGroupName === '') {
                renameLinkGroup(linkGroup.id, linkGroupName)
                linkGroup.title = linkGroupName
            }
        },
        openMergeModal(linkGroup) {
            this.mergeModal = { targetGroupId: linkGroup.linkGroup.id, selectedSourceIds: [], mode: 'intoTarget', selectedDestId: null }
            this.$modal.show('merge-groups')
        },
        confirmMerge() {
            if(this.mergeModal.mode === 'intoTarget') {
                if(this.mergeModal.selectedSourceIds.length === 0) return
                mergeGroups(this.mergeModal.targetGroupId, this.mergeModal.selectedSourceIds.map(id => Number(id)))
            } else {
                const dest = Number(this.mergeModal.selectedDestId)
                if(!dest) return
                mergeGroups(dest, [Number(this.mergeModal.targetGroupId)])
            }
            this.$modal.hide('merge-groups')
            this.mergeModal = { targetGroupId: null, selectedSourceIds: [], mode: 'intoTarget', selectedDestId: null }
        },
        openMoveMatching(linkGroup) {
            const hosts = this.uniqueHosts(linkGroup.links)
            this.moveMatching = { sourceGroupId: linkGroup.linkGroup.id, host: hosts[0] || '', hosts, selectedTargetId: null }
            this.$modal.show('move-matching')
        },
        confirmMoveMatching() {
            const fromGroup = this.links.find(g => g.linkGroup.id === this.moveMatching.sourceGroupId)
            if(!fromGroup) return
            const linkIds = fromGroup.links.filter(l => {
                try { return new URL(l.link).host === this.moveMatching.host } catch(e) { return false }
            }).map(l => l.id)
            // linkIds should be > 0 as host is derived from existing links; extra safety not needed
            moveLinks(this.moveMatching.selectedTargetId, linkIds)
            this.$modal.hide('move-matching')
            this.moveMatching = { sourceGroupId: null, host: '', hosts: [], selectedTargetId: null }
        }
    },
})

